// Lista de negocios activos de la plataforma para la app del domiciliario (React).
// Se usa para resolver el NOMBRE y el TEMA (color) del negocio del rider tras el
// login con PIN global (Opción A): GET /rider/businesses ? tenant_id del rider.
// Mantener al día al crear/editar un negocio (igual que INBOX_MAP en el relay).
// theme usa los mismos ids del dashboard (businesses.theme en MySQL):
// purpura | talos | calido | oscuro
return [{ json: { businesses: [
  { id: 1, name: 'Restaurante Demo - Sabor Autentico', theme: 'purpura' },
  { id: 3, name: 'Talos Sentinel', theme: 'talos' },
  { id: 4, name: 'Restaurante Demo', theme: 'calido' }
] } }];

// Prepara el mensaje interactivo de opt-in para la entrega hecha desde la app del rider.
// El phone_number_id del tenant se resuelve desde el mapa (igual que el relay).
const TENANT_PHONE = { 1: '1004464636088971', 3: '1095993256941270', 4: '1004464636088971' };
const TENANT_NAME  = { 1: 'Restaurante Demo - Sabor Auténtico', 3: 'Talos Sentinel', 4: 'Restaurante Demo' };
const order = $('PG Update Order Status').first().json;
const tenant = order.tenant_id;
const phoneNumberId = TENANT_PHONE[tenant] || '1004464636088971';
const customerPhone = order.customer_phone || '';

return [{
  json: {
    phone_number_id: phoneNumberId,
    to: customerPhone,
    payload: {
      messaging_product: 'whatsapp',
      to: customerPhone,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: '🎉 ¡Gracias por tu pedido en ' + (TENANT_NAME[tenant] || 'tu negocio') + '!\n\n¿Te gustaría recibir información sobre promociones y descuentos exclusivos por WhatsApp?' },
        action: {
          buttons: [
            { type: 'reply', reply: { id: 'optin_yes', title: 'Sí, me interesa! ✅' } },
            { type: 'reply', reply: { id: 'optin_no', title: 'No, gracias 🙏' } }
          ]
        }
      }
    }
  }
}];

// Extrae el texto del insight de la respuesta de DeepSeek.
const content = $json.choices?.[0]?.message?.content ?? 'No se pudo generar el insight.';
return [{ json: { insight: String(content).trim() } }];

// Construye la llamada a DeepSeek con los datos de analytics.
const analytics = $input.first().json.data;

const sys = `Eres un asesor comercial experto de un negocio de comida por WhatsApp. Analizas los datos de los últimos 30 días (productos, ventas por día de la semana, por hora y por zona) y redactas un análisis breve y accionable en español, como lo haría un buen vendedor:
1. Producto estrella y por qué destaca.
2. Productos de bajo rendimiento y qué hacer (promo, ajustar precio, retirar).
3. Mejor día y mejor hora para enviar una promoción, y qué promo sugerirías.
4. Zona con más demanda y una oportunidad concreta.
Sé concreto y usa cifras. Máximo 220 palabras. Usa viñetas simples (sin markdown pesado).`;

const user = "Datos de los últimos 30 días (JSON):\n" + JSON.stringify(analytics || {}, null, 1);

return [{
  json: {
    model: 'deepseek-chat',
    temperature: 0.7,
    max_tokens: 700,
    messages: [
      { role: 'system', content: sys },
      { role: 'user', content: user }
    ]
  }
}];

// Convierte el adjunto base64 del dashboard en binario para subirlo a Chatwoot (multipart).
const item = $input.first();
const { attachment } = item.json.body || {};
if (!attachment || !attachment.data_base64) {
  return [item];
}
const buffer = Buffer.from(attachment.data_base64, 'base64');
const binary = await this.helpers.prepareBinaryData(
  buffer,
  attachment.name || 'adjunto',
  attachment.mime || 'application/octet-stream'
);
return [{ json: item.json, binary: { data: binary } }];

