function simpleHash(pin) {
  let hash = 0;
  for (let i = 0; i < pin.length; i++) {
    hash = ((hash << 5) - hash) + pin.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(16).padStart(8, '0');
}

const pin = $json.body.pin?.toString();
if (!pin) throw new Error('PIN requerido');

const pinHash = simpleHash(pin);

// PINs son GLOBALMENTE únicos (verificados al crear el rider) → el login no
// necesita saber el negocio; el tenant se deriva del rider encontrado.
return [{ json: {
  pin_hash: pinHash,
  query: `SELECT id, name, is_active, tenant_id FROM delivery_riders WHERE pin_hash = '${pinHash}' AND is_active = true LIMIT 1;`
} }];

const items = $input.all();

// Si no hay token, saltar silenciosamente
if (!items[0]?.json?.fcm_token) {
  return [{ json: { skipped: true, reason: 'No FCM token' } }];
}

const fcmToken = items[0].json.fcm_token;
const riderName = items[0].json.name;
const orderId = $('PG Assign Rider').first().json.id;

// Leer service account
// La llave llega del .env como una sola línea con \n escapados:
// se convierten a saltos de línea reales antes de firmar el JWT.
const rawKey = ($env.FIREBASE_PRIVATE_KEY || '').replace(/\\n/g, '\n');
const serviceAccount = {
  project_id: $env.FIREBASE_PROJECT_ID,
  client_email: $env.FIREBASE_CLIENT_EMAIL,
  private_key: rawKey
};


// Generar JWT para OAuth2
const crypto = require('crypto');

const now = Math.floor(Date.now() / 1000);
const header = Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })).toString('base64url');
const payload = Buffer.from(JSON.stringify({
  iss: serviceAccount.client_email,
  scope: 'https://www.googleapis.com/auth/firebase.messaging',
  aud: 'https://oauth2.googleapis.com/token',
  iat: now,
  exp: now + 3600
})).toString('base64url');

const sign = crypto.createSign('RSA-SHA256');
sign.update(`${header}.${payload}`);
const signature = sign.sign(serviceAccount.private_key, 'base64url');
const jwt = `${header}.${payload}.${signature}`;

// Obtener access token
const https = require('https');

const postData = `grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=${jwt}`;

const accessToken = await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'oauth2.googleapis.com',
    path: '/token',
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Content-Length': Buffer.byteLength(postData)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => resolve(JSON.parse(data).access_token));
  });
  req.on('error', reject);
  req.write(postData);
  req.end();
});

// Enviar push FCM
const projectId = serviceAccount.project_id;
const fcmBody = JSON.stringify({
  message: {
    token: fcmToken,
    notification: {
      title: '🛵 Nuevo pedido asignado',
      body: `Pedido #${orderId} te fue asignado`
    },
    android: { priority: 'high' }
  }
});

const fcmResponse = await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'fcm.googleapis.com',
    path: `/v1/projects/${projectId}/messages:send`,
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(fcmBody)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('error', reject);
  req.write(fcmBody);
  req.end();
});

return [{ json: { success: true, fcmResponse: fcmResponse, rider: riderName } }];

