const { action, id, name, phone, pin, is_active, tenant_id } = $json.body;
if (tenant_id === undefined || tenant_id === null || tenant_id === '') 
{   throw new Error('Falta tenant_id: no se puede crear un domiciliario sin saber su negocio'); } 
const tenantId = tenant_id;

function simpleHash(pin) {
  let hash = 0;
  for (let i = 0; i < pin.length; i++) {
    hash = ((hash << 5) - hash) + pin.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(16).padStart(8, '0');
}

let query = '';
if (action === 'create') {
  if (!name || !pin) throw new Error('name y pin requeridos');
  const pinHash = simpleHash(pin.toString());
  // Guard: el PIN debe ser único entre TODOS los negocios (login global)
  query = `INSERT INTO delivery_riders (name, pin_hash, phone, tenant_id)
           SELECT '${name.replace(/'/g,"''")}', '${pinHash}', '${(phone || '').replace(/'/g,"''")}', ${tenantId}
           WHERE NOT EXISTS (SELECT 1 FROM delivery_riders WHERE pin_hash = '${pinHash}')
           RETURNING id, name, is_active;`;
} else if (action === 'update') {
  if (!id) throw new Error('id requerido');
  const setParts = [`name = '${name.replace(/'/g,"''")}' `, `updated_at = NOW()`];
  if (phone !== undefined) setParts.push(`phone = '${String(phone ?? '').replace(/'/g,"''")}'`);
  if (pin) {
    const pinHash = simpleHash(pin.toString());
    setParts.push(`pin_hash = '${pinHash}'`);
    query = `UPDATE delivery_riders SET ${setParts.join(', ')}
             WHERE id = ${id} AND tenant_id = ${tenantId}
               AND NOT EXISTS (SELECT 1 FROM delivery_riders WHERE pin_hash = '${pinHash}' AND id <> ${id})
             RETURNING id, name, is_active;`;
  } else {
    query = `UPDATE delivery_riders SET ${setParts.join(', ')} WHERE id = ${id} AND tenant_id = ${tenantId} RETURNING id, name, is_active;`;
  }
} else if (action === 'toggle') {
  if (!id) throw new Error('id requerido');
  query = `UPDATE delivery_riders SET is_active = ${is_active}, updated_at = NOW() WHERE id = ${id} AND tenant_id = ${tenantId} RETURNING id, name, is_active;`;
} else if (action === 'delete') {
  if (!id) throw new Error('id requerido');
  query = `DELETE FROM delivery_riders WHERE id = ${id} AND tenant_id = ${tenantId} RETURNING id;`;
} else {
  throw new Error('action inválida');
}

return [{ json: { query } }];

