// ── Token del domiciliario ───────────────────
// Se firma con HMAC-SHA256 usando el MISMO secreto que tiene el proxy del panel.
// El proxy verifica esta firma y compara el rider_id: así un tercero no puede
// actuar en nombre de un domiciliario aunque conozca su id.
const crypto = require('crypto');

const SECRETO = $env.RIDER_TOKEN_SECRET ||
  'TU_SECRETO_RIDER';
const DIAS = 30;

const r = $json; // fila de delivery_riders: { id, name, is_active, tenant_id }
const payload = {
  r: Number(r.id),
  t: Number(r.tenant_id),
  exp: Math.floor(Date.now() / 1000) + DIAS * 24 * 60 * 60,
};
const cuerpo = Buffer.from(JSON.stringify(payload)).toString('base64url');
const firma = crypto.createHmac('sha256', SECRETO).update(cuerpo).digest('base64url');

return [{ json: { ...r, token: `${cuerpo}.${firma}` } }];
